--- a/reminders/reminders_test.go
+++ b/reminders/reminders_test.go
@@ -1,10 +1,36 @@
 package reminders

 import (
	"testing"
	"time"
 )

+type stubRepo struct {
+	visit Visit
+}
+
+func (s *stubRepo) ByID(string) (Visit, error) { return s.visit, nil }
+
+func TestTextForVisit(t *testing.T) {
+	at := time.Date(2026, 6, 1, 9, 30, 0, 0, time.UTC)
+	repo := &stubRepo{visit: Visit{Pet: "Барсик", StartsAt: at}}
+	svc := New(repo)
+
+	got, err := svc.Text("v-1")
+	if err != nil {
+		t.Fatalf("неожиданная ошибка: %v", err)
+	}
+
+	want := text(repo.visit)
+	if got != want {
+		t.Fatalf("текст разошёлся: %q, ожидали %q", got, want)
+	}
+}
